-- Ongoing accountability is separate from care_visits.assigned_user_id and patient grants.
CREATE TABLE care_responsibilities (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), organization_id TEXT NOT NULL REFERENCES organizations(id), branch_id TEXT NOT NULL REFERENCES branches(id), consultant_id TEXT NOT NULL REFERENCES users(id), service TEXT NOT NULL, ward TEXT NOT NULL DEFAULT '', care_setting TEXT NOT NULL DEFAULT 'inpatient' CHECK(care_setting IN ('inpatient','ongoing')), specialty_review_reference TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','ended')), active_key TEXT UNIQUE, version INTEGER NOT NULL DEFAULT 1, request_key TEXT UNIQUE NOT NULL, request_payload_hash TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX responsibility_workspace ON care_responsibilities(organization_id,branch_id,status,updated_at);
CREATE INDEX responsibility_patient ON care_responsibilities(patient_id,status);
CREATE TABLE care_responsibility_events (id TEXT PRIMARY KEY, responsibility_id TEXT NOT NULL REFERENCES care_responsibilities(id), actor_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, action TEXT NOT NULL CHECK(action IN ('assigned','reassigned','ended')), reason TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(responsibility_id,version));
CREATE INDEX responsibility_events_history ON care_responsibility_events(responsibility_id,created_at);
